+import assert from 'node:assert/strict';
+import { after, before, describe, it } from 'node:test';
+import { parseImportCsv } from '../src/lib/csv.ts';
+import { api, startTestServer, type TestServer } from './helpers.ts';
+
+const HEADER = 'tracking,carrier,service,name,street,zip,city,country,phone';
+
+describe('quote-aware CSV import', () => {
+  it('keeps commas inside quoted fields', () => {
+    const rows = parseImportCsv(
+      `${HEADER}\nRR987654326AT,OEPOST,standard,"Müller, Hans","Hauptstr. 1, Top 4",1030,Wien,AT,+43 1`,
+    );
+    assert.equal(rows.length, 1);
+    assert.equal(rows[0].recipient.name, 'Müller, Hans');
+    assert.equal(rows[0].recipient.street, 'Hauptstr. 1, Top 4');
+    assert.equal(rows[0].recipient.zip, '1030');
+    assert.equal(rows[0].recipient.phone, '+43 1');
+  });
+
+  it('handles escaped quotes, CRLF and embedded newlines', () => {
+    const rows = parseImportCsv(`${HEADER}\r\nX1,DPDAT,,"Anna ""Annie"" B","a\nb",8010,Graz,,\r\n`);
+    assert.equal(rows.length, 1);
+    assert.equal(rows[0].recipient.name, 'Anna "Annie" B');
+    assert.equal(rows[0].recipient.street, 'a\nb');
+    assert.equal(rows[0].carrier, 'DPD');
+    assert.equal(rows[0].recipient.country, 'AT');
+  });
+
+  describe('POST /import', () => {
+    let srv: TestServer;
+    before(async () => {
+      srv = await startTestServer();
+    });
+    after(async () => {
+      await srv.close();
+    });
+
+    it('imports a recipient name containing a comma', async () => {
+      const csv = `${HEADER}\nRR987654326AT,OEPOST,standard,"Müller, Hans",Herrengasse 12,1010,Wien,AT,`;
+      const res = await api(srv.url, 'POST', '/import', csv);
+      assert.equal(res.body.created, 1);
+      assert.deepEqual(res.body.errors, []);
+      const s = srv.store.findByTrackingNumber('RR987654326AT');
+      assert.equal(s?.recipient.name, 'Müller, Hans');
+      assert.equal(s?.recipient.zip, '1010');
+    });
+  });
+});
